sections.code:
-- PostgreSQL
SELECT DATE_TRUNC('month', order_date) AS month
FROM orders;

-- SQLite lab equivalent
SELECT strftime('%Y-%m-01', order_date) AS month
FROM orders;

SELECT DISTINCT region, channel
FROM orders
ORDER BY region, channel;

SELECT order_id, order_date, region
FROM orders
WHERE region = 'Dhaka';

SELECT product_name, list_price
FROM products
WHERE list_price >= 50;

SELECT customer_name, city
FROM customers
WHERE customer_name LIKE 'A%';

SELECT customer_id, customer_name, city
FROM customers
WHERE city IS NULL;

SELECT quantity, unit_price, discount_pct,
       quantity * unit_price * (1 - discount_pct) AS net_revenue
FROM order_items;

SELECT customer_name, COALESCE(city, 'Unknown') AS city_label
FROM customers;

SELECT revenue / NULLIF(order_count, 0) AS average_order_value;

SELECT region, channel, status, COUNT(*) AS orders
FROM orders
GROUP BY region, channel, status;

SELECT o.order_id, c.customer_name, o.order_date
FROM orders o
INNER JOIN customers c ON c.customer_id = o.customer_id;

SELECT e.employee_name, m.employee_name AS manager_name
FROM employees e
LEFT JOIN employees m ON m.employee_id = e.manager_id;

SELECT r.region, c.channel
FROM (SELECT DISTINCT region FROM orders) r
CROSS JOIN (SELECT DISTINCT channel FROM orders) c;

SELECT 'Customer' AS entity, customer_name AS name FROM customers
UNION ALL
SELECT 'Employee', employee_name FROM employees;

SELECT c.customer_id, c.customer_name
FROM customers c
WHERE NOT EXISTS (
  SELECT 1 FROM orders o WHERE o.customer_id=c.customer_id
);

SELECT product_name, list_price
FROM products
WHERE list_price > (SELECT AVG(list_price) FROM products);

SELECT p.product_name, p.list_price
FROM products p
WHERE p.list_price > (
  SELECT AVG(p2.list_price) FROM products p2 WHERE p2.category=p.category
);

SELECT p.product_id, p.product_name
FROM products p
WHERE EXISTS (
  SELECT 1 FROM order_items oi WHERE oi.product_id=p.product_id
);

WITH order_totals AS (
  SELECT order_id, SUM(quantity*unit_price*(1-discount_pct)) AS revenue
  FROM order_items
  GROUP BY order_id
)
SELECT AVG(revenue) AS average_order_value FROM order_totals;

SELECT order_id, region, order_date,
       COUNT(*) OVER (PARTITION BY region) AS region_orders
FROM orders;

SELECT product_name, category, list_price,
       DENSE_RANK() OVER (PARTITION BY category ORDER BY list_price DESC) AS price_rank
FROM products;

WITH daily AS (
 SELECT order_date, COUNT(*) AS orders FROM orders GROUP BY order_date
)
SELECT order_date, orders,
       SUM(orders) OVER (ORDER BY order_date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_orders
FROM daily;

WITH monthly AS (SELECT strftime('%Y-%m',order_date) AS month,COUNT(*) AS orders FROM orders GROUP BY 1)
SELECT month,orders,LAG(orders) OVER (ORDER BY month) AS previous_orders
FROM monthly;

SELECT customer_id, order_date,
       FIRST_VALUE(order_date) OVER (PARTITION BY customer_id ORDER BY order_date) AS first_order
FROM orders;

WITH customer_revenue AS (...)
SELECT customer_id,revenue,NTILE(4) OVER (ORDER BY revenue DESC) AS value_quartile
FROM customer_revenue;

WITH ranked AS (
 SELECT product_id,product_name,category,list_price,
        ROW_NUMBER() OVER (PARTITION BY category ORDER BY list_price DESC,product_id) AS rn
 FROM products
)
SELECT * FROM ranked WHERE rn <= 2;

CREATE TABLE targets (
  target_month DATE NOT NULL,
  region TEXT NOT NULL,
  revenue_target NUMERIC CHECK (revenue_target >= 0),
  PRIMARY KEY (target_month, region)
);

